def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    colors = set(v for row in grid for v in row if v != bg)

    # Find solid rectangular borders and fill their interiors.
    for c in colors:
        for r1 in range(h):
            for r2 in range(r1 + 2, h):
                for c1 in range(w):
                    for c2 in range(c1 + 2, w):
                        if (all(grid[r1][x] == c and grid[r2][x] == c for x in range(c1, c2 + 1))
                            and all(grid[y][c1] == c and grid[y][c2] == c for y in range(r1, r2 + 1))):
                            fill = 7 if c == 5 else 2
                            for y in range(r1 + 1, r2):
                                for x in range(c1 + 1, c2):
                                    if grid[y][x] == bg:
                                        out[y][x] = fill
    return out
